/* Veelad Creative: personal briefs, artist-led layouts and a moderated community. */
'use strict';
window.VeeladCreative = (() => {
  let data = {}, activeRoute = '', activeParams = new URLSearchParams(), lastGuide = null;
  const say = (en, ar) => currentLanguage() === 'ar' ? ar : t(en);
  const e = value => esc(value ?? '');
  const local = (record, key) => currentLanguage() === 'ar' && record?.[key + '_ar'] ? record[key + '_ar'] : record?.[key] || '';
  const number = value => typeof localNumber === 'function' ? localNumber(Number(value || 0)) : String(value || 0);
  const href = (route, params = {}) => e(url(route, params));
  const anchor = (text, route, cls = '', params = {}) => `<a class="${cls}" href="${href(route, params)}">${text}</a>`;
  const action = (text, name, attrs = '', cls = 'btn outline sm') => `<button type="button" class="${cls}" data-creative-action="${name}" ${attrs}>${text}</button>`;
  const optionId = option => typeof option === 'string' ? option : option.id || option.value;
  const optionName = option => typeof option === 'string' ? label(option) : currentLanguage() === 'ar' ? option.ar || option.label_ar || option.en || option.label || option.id : option.en || option.label || option.id;
  const label = id => ({
    birthday:['Birthday','عيد ميلاد'],anniversary:['Anniversary','ذكرى جميلة'],graduation:['Graduation','تخرّج'],friendship:['Friendship','صداقة'],thank_you:['Thank you','شكر وتقدير'],everyday:['Just because','بدون مناسبة'],wedding:['Wedding','زواج'],new_home:['New home','بيت جديد'],celebration:['Celebration','احتفال'],
    playful:['Playful','مرح'],bold:['Bold','جريء'],minimal:['Minimal','بسيط'],nostalgic:['Nostalgic','حنين'],sentimental:['Sentimental','قريب للقلب'],calm:['Calm','هادئ'],elegant:['Elegant','أنيق'],funny:['Funny','خفيف دم'],
    approved:['Published','منشور'],published:['Published','منشور'],pending:['In review','قيد المراجعة'],draft:['Draft','مسودة'],rejected:['Changes needed','يحتاج تعديل'],cancelled:['Cancelled','ملغي'],archived:['Archived','مؤرشف']
  }[id] ? say(...({birthday:['Birthday','عيد ميلاد'],anniversary:['Anniversary','ذكرى جميلة'],graduation:['Graduation','تخرّج'],friendship:['Friendship','صداقة'],thank_you:['Thank you','شكر وتقدير'],everyday:['Just because','بدون مناسبة'],wedding:['Wedding','زواج'],new_home:['New home','بيت جديد'],celebration:['Celebration','احتفال'],playful:['Playful','مرح'],bold:['Bold','جريء'],minimal:['Minimal','بسيط'],nostalgic:['Nostalgic','حنين'],sentimental:['Sentimental','قريب للقلب'],calm:['Calm','هادئ'],elegant:['Elegant','أنيق'],funny:['Funny','خفيف دم'],approved:['Published','منشور'],published:['Published','منشور'],pending:['In review','قيد المراجعة'],draft:['Draft','مسودة'],rejected:['Changes needed','يحتاج تعديل'],cancelled:['Cancelled','ملغي'],archived:['Archived','مؤرشف']}[id])) : t(String(id || '').replaceAll('_',' ')));
  const optionList = (name, fallback = []) => data.discover?.options?.[name]?.length ? data.discover.options[name] : fallback;
  const field = (title, name, value = '', attrs = '', type = 'text') => `<label class="field"><span>${title}</span><input name="${name}" type="${type}" value="${e(value)}" ${attrs}></label>`;
  const area = (title, name, value = '', attrs = '') => `<label class="field"><span>${title}</span><textarea name="${name}" rows="4" ${attrs}>${e(value)}</textarea></label>`;
  const select = (title, name, options, value = '', attrs = '') => `<label class="field"><span>${title}</span><select name="${name}" ${attrs}>${options.map(option => `<option value="${e(optionId(option))}" ${String(optionId(option)) === String(value) ? 'selected' : ''}>${e(optionName(option))}</option>`).join('')}</select></label>`;
  const check = (title, name, checked = false, attrs = '') => `<label class="creative-check"><input type="checkbox" name="${name}" ${checked ? 'checked' : ''} ${attrs}><span>${title}</span></label>`;
  const badge = status => `<span class="creative-status" data-status="${e(status)}">${e(label(status))}</span>`;
  const title = (kicker, heading, description, tools = '') => `<header class="creative-title"><div><p class="creative-kicker">${kicker}</p><h1>${heading}</h1><p>${description}</p></div>${tools}</header>`;
  const notice = (en, ar) => `<p class="creative-notice">${say(en, ar)}</p>`;
  const empty = (en, ar, detailEn, detailAr, cta = '') => `<div class="creative-empty">${icon('star')}<h2>${say(en,ar)}</h2><p>${say(detailEn,detailAr)}</p>${cta}</div>`;
  const date = value => value ? new Intl.DateTimeFormat(currentLanguage() === 'ar' ? 'ar-SA' : 'en-GB', {dateStyle:'medium',calendar:'gregory'}).format(new Date(value)) : '';
  function linkToProduct(product, text = '') { return anchor(text || say('Explore this product','شوف المنتج'), 'product', 'text-link', {id:product.id}); }
  function picture(product, cls = '', loading = 'lazy') {
    const src = currentLanguage() === 'ar' && product?.image_url_ar ? product.image_url_ar : product?.image_url;
    return src && /^\/(?!\/)/.test(src) ? `<img class="${cls}" src="${e(src)}" alt="${e(local(product,'title'))}" width="720" height="720" loading="${loading}" decoding="async">` : `<div class="creative-product-placeholder" aria-hidden="true">${icon('image')}</div>`;
  }
  function productCards(items = [], reasons = true, eager = false) {
    if (!items.length) return empty('A little more inspiration is on its way.','الإلهام الجاي بالطريق.','No available products match these choices yet. Try a wider budget or another category.','ما فيه منتجات متاحة تناسب هالاختيارات حاليًا. جرّب توسّع الميزانية أو تغيّر نوع المنتج.');
    return `<div class="creative-product-grid">${items.map(item => {
      const product = item.product || item;
      return `<article class="creative-product-card">${anchor(picture(product,'',eager?'eager':'lazy'), 'product', 'creative-product-image', {id:product.id})}<div>${product.sample_pricing ? `<span class="creative-small-label">${say('Sample price','سعر تجريبي')}</span>` : ''}<h3>${anchor(e(local(product,'title')), 'product', '', {id:product.id})}</h3><p>${e(t(product.category || ''))}</p><strong>${money(product.price)}</strong>${reasons && (item.reason || item.reason_ar || item.reasons?.length) ? `<p class="creative-match-reason">${icon('check')}${e(local(item,'reason') || (item.reasons || []).map(reason => typeof reason === 'string' ? reason : local(reason,'label')).join(' · '))}</p>` : ''}</div></article>`;
    }).join('')}</div>`;
  }
  function navigation() {
    const links = [
      ['creative','Discover','اكتشف','star'],['creative/story','Your story','حكايتك','edit'],['creative/gifts','Gift studio','استوديو الهدايا','bag'],['creative/templates','Artist layouts','قوالب الفنانين','palette'],['creative/rooms','Design together','صمّموا سوا','partnership'],['creative/taste','Your taste','ذوقك','heart'],['creative/wishes','Wish board','لوحة الأفكار','plus'],['creative/stories','Behind the design','وراء التصميم','image'],['creative/sample-room','Sample room','غرفة المعاينة','package']
    ];
    return `<nav class="creative-navigation container" aria-label="${say('Creative experiences','مساحات الإبداع')}">${links.map(([route,en,ar,symbol]) => `<a href="${href(route)}" ${activeRoute === route || activeRoute.startsWith(route + '/') && route !== 'creative' ? 'aria-current="page"' : ''}>${icon(symbol)}<span>${say(en,ar)}</span></a>`).join('')}</nav>`;
  }
  function shell(content, extra = '') { return `<main id="main" class="creative-page ${extra}">${navigation()}${content}</main>`; }
  function signIn(next = activeRoute) {
    return `<section class="container creative-signin">${title(say('ONE ACCOUNT. YOUR WHOLE CREATIVE WORLD.','حساب واحد، لكل أفكارك.'),say('Make room for your next idea.','خلّ لفكرتك مكان.'),say('Sign in to keep your briefs private, save your taste and create with the community.','سجّل دخولك عشان تحفظ أفكارك بخصوصية، وتختار اللي يناسب ذوقك، وتشارك في المجتمع.'))}<div class="creative-actions">${anchor(say('Sign in','تسجيل الدخول'),'login','btn',{next})}${anchor(say('Create an account','إنشاء حساب'),'register','btn outline',{next})}</div></section>`;
  }
  function landing() {
    const experiences = [
      ['01','creative/story','A story only you can tell.','حكاية ما تشبه إلا حكايتك.','A memory, an inside joke, a person you love. Find a thoughtful starting point and make it yours.','ذكرى، نكتة بينكم، أو شخص غالي. نرتّب فكرتك في بداية جميلة، وتكملها بطريقتك.','edit','lilac'],
      ['02','creative/gifts','Better than “what should I get?”','هدية تقول: أعرفك.','Start with the person and the feeling. Discover products and personal touches that make sense together.','ابدأ بالشخص والإحساس اللي تبي توصّله. واكتشف منتجات ولمسات شخصية تناسب بعض.','bag','peach'],
      ['03','creative/templates','An artist’s eye. Your finishing touch.','لمسة فنان، وبصمتك أنت.','Discover original layouts with artist-approved spaces for your words, names and moments.','قوالب أصلية يحدد فيها الفنان مساحة لكلماتك وأسمائك ولحظاتك.','palette','green'],
      ['04','creative/rooms','Good ideas love company.','أحلى الأفكار، نطلعها سوا.','Invite your people into a private design room. Share ideas, vote and agree on the final direction.','اجمع ناسك في غرفة خاصة. تبادلوا الأفكار، وصوّتوا، واتفقوا على الشكل الأخير.','partnership','blue'],
      ['05','creative/taste','A corner of Veelad that feels like you.','ركن في فيلاد، على ذوقك.','Choose a few visual favourites. Your saved preferences help shape useful recommendations.','اختر اللي يلفت نظرك. نحفظ تفضيلاتك بإذنك عشان نقرّب لك الاختيارات اللي تحبها.','heart','rose'],
      ['06','creative/wishes','“I wish someone made this.”','«يا ليت أحد يصمّمها».','Put your idea into the world. Follow the ones you love and see how artists respond.','شارك الفكرة اللي تتمنى تشوفها. تابع اللي يعجبك، وشوف كيف يرد عليها الفنانون.','plus','yellow'],
      ['07','creative/stories','Every design has a beginning.','كل تصميم وراه حكاية.','Meet the thought, process and people behind original work. Keep the story with the finished piece.','تعرّف على الفكرة والخطوات والناس وراء العمل. وخلّ الحكاية ترافق القطعة.','image','lilac'],
      ['08','creative/sample-room','Look a little closer.','خذ نظرة أقرب.','Explore the product, available views and print details before you open your design in the editor.','شوف المنتج وزواياه وتفاصيل المعاينة قبل تبدأ تصميمك في المحرر.','package','green']
    ];
    const picks=data.discover?.recommendations?.slice(0,4)||[];
    return shell(`
      <section class="creative-hero container" aria-labelledby="creative-home-title">
        <div class="creative-hero-copy">
          <p class="creative-kicker">${say('YOUR IDEA. YOUR PERSONAL TOUCH.','فكرتك، بلمستك.')}</p>
          <h1 id="creative-home-title">${say('Make something.<br><em>Make it yours.</em>','ابتكر شي.<br><em>وخله يشبهك.</em>')}</h1>
          <p class="creative-hero-description">${say('A shared memory. A gift that gets them. An idea only you could have. Turn it into something for everyday life.','ذكرى تجمعكم، هدية تقول إنك تعرفه، أو فكرة ما تجي إلا منك. صمّم منها قطعة تعيش معكم كل يوم.')}</p>
          <div class="creative-actions">
            ${anchor(say('Start with your story','ابدأ بحكايتك'),'creative/story','btn')}
            ${anchor(say('Find a thoughtful gift','اختار هدية بمعنى'),'creative/gifts','btn outline')}
          </div>
          <div class="creative-hero-details"><span>${icon('edit')}${say('Your words, your design','كلماتك وتصميمك')}</span><span>${icon('package')}${say('Seven product types','سبعة أنواع من المنتجات')}</span></div>
        </div>
        <figure class="creative-hero-photo">
          <img src="/assets/lifestyle/creative-studio.webp" alt="${say('An illustrative creative studio with two people arranging artwork and colours','مشهد تصوّري لشخصين يرتبان تصاميم وألوانًا في استوديو إبداعي')}" width="1200" height="1000" fetchpriority="high" decoding="async">
          <div class="creative-photo-label"><span aria-hidden="true">✳</span><span>${say('A little inspiration.<br>A lot of you.','شوي إلهام.<br>وكثير منك.')}</span></div>
          <figcaption>${say('Illustrative campaign image, created with AI.','صورة تصوّرية للحملة، مولّدة بالذكاء الاصطناعي.')}</figcaption>
        </figure>
      </section>
      <section class="creative-manifesto" aria-label="${say('Made personal','قطعة لها معنى')}"><div class="container"><span>${say('SMALL DETAILS. REAL MEANING.','التفاصيل الصغيرة، تعني الكثير.')}</span><p>${say('From “I have an idea” to “this is so you.”','من «عندي فكرة» إلى «هذي تشبهك مرّة».')}</p></div></section>
      <section class="container creative-section creative-pathways" aria-labelledby="creative-pathways-title">
        <div class="creative-section-heading"><div><p class="creative-kicker">${say('FIND YOUR STARTING POINT','اختر بدايتك')}</p><h2 id="creative-pathways-title">${say('What will you make yours?','وش ودّك تخليه على ذوقك؟')}</h2></div><p>${say('Eight ways to start. Every one leads somewhere different.','ثمان بدايات مختلفة. وكل وحدة توصّلك لشي يخصّك.')}</p></div>
        <div class="creative-experience-grid">${experiences.map(([n,path,en,ar,de,da,symbol,color])=>anchor(`<div class="creative-card-top"><span class="creative-experience-icon">${icon(symbol)}</span><span class="creative-experience-number">${n}</span></div><h3>${say(en,ar)}</h3><p>${say(de,da)}</p><span class="creative-experience-cta">${say('Explore','اكتشف')}${icon('arrow')}</span>`,path,'creative-experience-card '+color)).join('')}</div>
      </section>
      <section class="container creative-community-section" aria-labelledby="creative-community-title"><div class="creative-community-strip">
        <div class="creative-community-art" aria-hidden="true"><span class="creative-note creative-note-first">YOUR<br>IDEA.</span><span class="creative-note-spark">✳</span><span class="creative-note creative-note-second" lang="ar" dir="rtl">فكرتك<br>تستاهل.</span></div>
        <div class="creative-community-copy"><p class="creative-kicker">${say('GOOD IDEAS START CONVERSATIONS','الفكرة الحلوة تفتح سالفة')}</p><h2 id="creative-community-title">${say('Wish it existed?<br>Tell the artists.','تتمنى أحد يصمّمها؟<br>قل للفنانين.')}</h2><p>${say('Share the design you wish you could find, support an idea you love, and see how independent artists respond.','شارك التصميم اللي تتمنى تلقاه، وساند فكرة تعجبك، وشوف كيف يرد عليها الفنانون.')}</p>${anchor(say('Explore the wish board','شوف لوحة الأفكار')+' '+icon('arrow'),'creative/wishes','btn outline')}</div>
      </div></section>
      ${picks.length?`<section class="container creative-section creative-picks" aria-labelledby="creative-picks-title"><div class="creative-section-heading"><div><p class="creative-kicker">${say('ORIGINAL ART. EVERYDAY THINGS.','فن أصلي، لأشياء كل يوم.')}</p><h2 id="creative-picks-title">${data.discover.taste?say('A little closer to your taste.','أقرب لذوقك.'):say('A few things to spark an idea.','قطع ممكن تلهمك.')}</h2></div>${anchor(say('Find your taste','اكتشف ذوقك'),'creative/taste','text-link')}</div>${productCards(picks,false,true)}</section>`:''}
      <section class="container creative-closing-section"><div class="creative-final-invite"><div><p class="creative-kicker">${say('MAKE ROOM FOR YOUR OWN IDEAS','خلّ لأفكارك مساحة')}</p><h2>${say('Your next favourite.<br>Designed by you.','قطعتك المفضّلة الجاية.<br>من تصميمك.')}</h2><p>${say('Bring a photo, a few words, or a completely new idea.','ابدأ بصورة، كم كلمة، أو فكرة جديدة من عندك.')}</p></div><div class="creative-actions">${anchor(say('Open the design studio','افتح استوديو التصميم')+' '+icon('arrow'),'create','btn light')}${user&&['artist','admin'].includes(user.role)?anchor(say('Your artist workspace','مساحتك كفنان'),'creative/workspace','text-link'):''}</div></div></section>
    `,'creative-home');
  }
  function guideForm(kind) {
    const gift = kind === 'gift';
    const categories = [{id:'',en:'Any available product',ar:'أي منتج متاح'},...optionList('categories',[])];
    return shell(`<section class="container creative-section">${title(gift ? say('THE GIFT STUDIO','استوديو الهدايا') : say('DESIGN MY STORY','صمّم حكايتي'),gift ? say('Let’s start with<br>who they are.','نبدأ بالشخص،<br>مو بالهدية.') : say('Every good design<br>starts with something real.','التصميم الحلو،<br>يبدأ من شي له معنى.'),gift ? say('Tell us a little about the person. We’ll match your choices with available products and editable starting points.','عرّفنا شوي بالشخص. نقرّب لك منتجات متاحة وبدايات تقدر تعدّلها على ذوقه.') : say('A memory, a favourite place, a phrase only you understand. We’ll turn your brief into a structured design direction you can edit.','ذكرى، مكان تحبه، أو عبارة ما يفهمها إلا أنتم. نرتّب فكرتك في اتجاه تصميم واضح، وتكمّله بطريقتك.'))}<div class="creative-guide-layout"><form class="creative-form creative-panel" data-creative-form="${gift ? 'gift' : 'brief'}"><div class="creative-step-label">01 / ${say('Tell us the feeling','وش الإحساس اللي تبي توصّله؟')}</div>${field(say('Who is it for?','لمين التصميم؟'),'recipient','','required maxlength="120" placeholder="'+say('My sister, a friend, myself…','أختي، صديق، لنفسي…')+'"')}${select(say('The occasion','المناسبة'),'occasion',optionList('occasions',['everyday','birthday','graduation','anniversary']))}${area(gift ? say('What do they love?','وش يحب؟') : say('Tell the story','احكِ لنا الفكرة'),'story','',(gift?'':'required ')+'maxlength="1800" placeholder="'+say('Details make it personal: a colour, a place, a shared memory…','التفاصيل تعطيها معنى: لون، مكان، ذكرى بينكم…')+'"')}<div class="creative-form-grid">${select(say('The feeling','الإحساس'),'mood',optionList('moods',['playful','minimal','sentimental','bold']))}${select(say('Product type','نوع المنتج'),'category',categories)}${field(say('Budget per item · SAR','ميزانيتك للقطعة · ريال'),'budget','','min="0" max="100000" step="0.01" placeholder="'+say('Optional','اختياري')+'"','number')}</div>${gift ? check(say('Save this gift brief privately in my account','احفظ فكرة الهدية بخصوصية في حسابي'),'save',false,user ? '' : 'disabled') : ''}<p class="creative-help">${say('Guided template matching, not an AI image generator. Your words stay editable. Product previews and delivery availability need their normal review.','هذي مطابقة بقوالب واتجاهات تصميم، مو مولّد صور بالذكاء الاصطناعي. كلماتك تبقى قابلة للتعديل، والمعاينات والتوصيل لها مراجعتها المعتادة.')}</p><button class="btn" type="submit">${gift ? say('Find a thoughtful direction','اقترح لي هدية بمعنى') : say('Find my design direction','رتّب لي اتجاه التصميم')} ${icon('arrow')}</button><div data-creative-form-status role="status" aria-live="polite"></div></form><aside class="creative-guide-aside"><div class="creative-prompt-card"><span>✳</span><p>${gift ? say('The best gifts say,<br>“I noticed.”','أجمل هدية تقول:<br>«انتبهت للي تحبّه».') : say('Not just a name<br>on a product.<br><em>A little piece of you.</em>','مو بس اسم<br>على منتج.<br><em>قطعة صغيرة منك.</em>')}</p></div><h3>${say('The details are the difference.','التفاصيل هي الفرق.')}</h3><ul><li>${say('A name, a place or a date','اسم، مكان، أو تاريخ')}</li><li>${say('A colour they always choose','لون دايم يختاره')}</li><li>${say('A feeling you want to keep','إحساس تبي تحتفظ فيه')}</li></ul></aside></div><section class="creative-guide-results" data-creative-results aria-live="polite"></section></section>`);
  }
  function guideResults(result) {
    const brief = result.brief || result, concept = brief.concept || result.concept || {}, recommendations = brief.recommendations || result.recommendations || [];
    const palette = concept.palette || ['#c8b4e9','#263228','#edc7a7'];
    return `<div class="creative-result-heading"><p class="creative-kicker">02 / ${say('YOUR STARTING POINT','بداية تصميمك')}</p><h2>${e(local(concept,'title') || say('A direction worth making your own.','اتجاه يستاهل تكمله بطريقتك.'))}</h2><p>${say('This is a starting composition, not a finished printed product. Open it in the editor to make it yours.','هذي بداية للتصميم، مو منتج مطبوع جاهز. افتحها في المحرر وأضف لمستك.')}</p></div><div class="creative-concept-grid"><div class="creative-concept-sample" style="--concept-color:${/^#[0-9a-f]{6}$/i.test(palette[0]) ? e(palette[0]) : '#c8b4e9'}"><span>${e(concept.headline || brief.recipient || say('YOUR STORY','حكايتك'))}</span><p>${e(concept.caption || brief.story || '')}</p><small>${say('Editable composition direction','اتجاه تصميم قابل للتعديل')}</small></div><div class="creative-concept-detail"><div class="creative-palette">${palette.filter(color => /^#[0-9a-f]{6}$/i.test(color)).map(color => `<span style="background:${e(color)}" aria-label="${e(color)}"></span>`).join('')}</div><h3>${say('Keep the feeling. Make the details yours.','خلّ الإحساس، وعدّل التفاصيل بطريقتك.')}</h3><p>${e(local(concept,'description') || local(concept,'caption') || '')}</p>${recommendations.length ? `<label class="field"><span>${say('Open on an available item','افتحه على منتج متاح')}</span><select data-creative-guide-product>${recommendations.map(item => {const p=item.product||item;return `<option value="${e(p.id)}">${e(local(p,'title'))} · ${money(p.price)}</option>`;}).join('')}</select></label>${action(say('Make this design mine','أكمل التصميم بلمستي'),'start-concept','','btn')}` : anchor(say('Explore the design studio','استكشف استوديو التصميم'),'create','btn')}<p class="creative-help">${say('Nothing is ordered or charged by creating a brief.','إنشاء الفكرة ما ينشئ طلب ولا يسحب أي مبلغ.')}</p></div></div>${recommendations.length ? `<div class="creative-section-heading"><h3>${say('Products that fit the direction','منتجات تناسب الاتجاه')}</h3></div>${productCards(recommendations)}` : productCards([])}`;
  }
  function taste() {
    if (!user) return shell(signIn());
    const taste = data.discover.taste || {}, styles = optionList('styles',[]), colors=optionList('colors',['#25283d','#bda8e0','#d8e4cc','#e9b698','#e8dca7']), moods=optionList('moods',['playful','minimal','sentimental']);
    return shell(`<section class="container creative-section">${title(say('YOUR CREATIVE UNIVERSE','عالمك الإبداعي'),say('What catches<br>your eye?','وش اللي<br>يلفت نظرك؟'),say('Choose a few things you’re drawn to. Save them only if you want more personal recommendations. You can change or delete them whenever you like.','اختر الأشياء اللي تميل لها. نحفظها إذا حبيت عشان تصير اقتراحاتنا أقرب لك. وتقدر تغيّرها أو تحذفها في أي وقت.'))}<form class="creative-form" data-creative-form="taste">${taste.version ? `<input type="hidden" name="version" value="${e(taste.version)}">` : ''}<fieldset class="creative-choice-fieldset"><legend>${say('01 / Visual worlds','01 / عوالم بصرية')}</legend><div class="creative-taste-grid">${styles.map((style,index) => {const id=optionId(style);return `<label class="creative-taste-card"><input type="checkbox" name="styles" value="${e(id)}" ${taste.styles?.includes(id)?'checked':''}><span class="creative-taste-art creative-art-${index%6}" aria-hidden="true"><i></i><i></i><i></i></span><strong>${e(optionName(style))}</strong><span class="creative-choice-mark" aria-hidden="true">${icon('check')}</span></label>`;}).join('')}</div></fieldset><fieldset class="creative-choice-fieldset"><legend>${say('02 / Colours you come back to','02 / ألوان ترجع لها دايم')}</legend><div class="creative-colour-choices">${colors.map(color => {const id=optionId(color),hex=/^#[0-9a-f]{6}$/i.test(id)?id:'#ddd';return `<label><input type="checkbox" name="colors" value="${e(id)}" ${taste.colors?.includes(id)?'checked':''}><span style="background:${e(hex)}">${icon('check')}</span><small>${e(id)}</small></label>`;}).join('')}</div></fieldset><fieldset class="creative-choice-fieldset"><legend>${say('03 / How should it feel?','03 / وش الإحساس؟')}</legend><div class="creative-chip-choices">${moods.map(mood => {const id=optionId(mood);return `<label><input type="checkbox" name="moods" value="${e(id)}" ${taste.moods?.includes(id)?'checked':''}><span>${e(optionName(mood))}</span></label>`;}).join('')}</div></fieldset><div class="creative-taste-save creative-panel">${check(say('I want Veelad to save these preferences to personalise my recommendations.','أوافق إن فيلاد يحفظ هالتفضيلات عشان يقرّب اقتراحاته لذوقي.'),'consent',taste.consent===true,'required')}<p>${say('No location tracking or advertising profile. This is your account preference, not a promise that every recommendation will match.','بدون تتبّع موقع أو ملف إعلاني. هذي تفضيلات حسابك، وما تعني إن كل اقتراح بيطابق ذوقك تمامًا.')}</p><div class="creative-actions"><button type="submit" class="btn">${say('Save my creative taste','احفظ ذوقي')}${icon('heart')}</button>${taste.consent ? action(say('Delete my saved preferences','احذف تفضيلاتي المحفوظة'),'delete-taste','','text-link') : ''}</div><div data-creative-form-status role="status" aria-live="polite"></div></div></form>${data.discover.recommendations?.length ? `<section class="creative-section"><h2>${say('A few things to explore.','اختيارات تستاهل نظرة.')}</h2>${productCards(data.discover.recommendations.slice(0,4))}</section>` : ''}</section>`);
  }
  function wishCard(wish) {
    return `<article class="creative-wish-card"><div class="creative-card-top"><span>${e(t(wish.category || say('An idea','فكرة')))}</span>${wish.status && wish.status!=='approved' ? badge(wish.status) : ''}</div><h3>${anchor(e(local(wish,'title')),'creative/wishes','',{id:wish.id})}</h3><p>${e(local(wish,'description'))}</p><div class="creative-wish-footer"><span>${icon('heart')}${number(wish.vote_count)} ${say('interested','مهتم')}</span><span>${icon('users')}${number(wish.follower_count)} ${say('following','متابع')}</span>${anchor(say('See the idea','شوف الفكرة')+' '+icon('arrow'),'creative/wishes','text-link',{id:wish.id})}</div></article>`;
  }
  function wishForm(wish = {}) {
    return `<form class="creative-form creative-panel" data-creative-form="wish">${wish.id ? `<input type="hidden" name="id" value="${e(wish.id)}"><input type="hidden" name="version" value="${e(wish.version)}">` : ''}<h2>${say('What do you wish existed?','وش الفكرة اللي تتمنى تشوفها؟')}</h2><p>${say('A clear brief helps artists understand the possibility. Your idea is reviewed before it appears publicly.','الفكرة الواضحة تساعد الفنان يشوف إمكانياتها. نراجع اقتراحك قبل ما يظهر للكل.')}</p>${field(say('Give the idea a title','عنوان الفكرة'),'title',wish.title||'','required maxlength="160"')}${area(say('Describe the idea','وصف الفكرة'),'description',wish.description||'','required maxlength="2400"')}${select(say('Product type','نوع المنتج'),'category',[{id:'',en:'Open to possibilities',ar:'مفتوح لاقتراحات'},...optionList('categories',[])],wish.category||'')}<div class="creative-actions"><button class="btn" type="submit" name="action" value="submit">${say('Send for review','أرسلها للمراجعة')}</button><button class="btn outline" type="submit" name="action" value="draft">${say('Save privately','احفظها بخصوصية')}</button></div><p class="creative-help">${say('Interest is not a preorder, a commission contract or a promise of production. Don’t include private contact details or material you do not have permission to share.','الاهتمام بالفكرة مو طلب مسبق، ولا اتفاق تكليف، ولا وعد بالإنتاج. لا تكتب بيانات تواصل خاصة أو مواد ما عندك إذن بمشاركتها.')}</p><div data-creative-form-status role="status" aria-live="polite"></div></form>`;
  }
  function wishes() {
    const detail=data.wish?.wish;
    if (detail) {
      const concepts=data.wish.concepts||[];
      return shell(`<section class="container creative-section">${anchor('← '+say('All ideas','كل الأفكار'),'creative/wishes','text-link')}${title(say('THE WISH BOARD','لوحة الأفكار'),e(local(detail,'title')),e(local(detail,'description')))}<div class="creative-wish-detail"><div class="creative-panel"><span class="creative-small-label">${e(t(detail.category||''))}</span><p>${say('An idea shared by','فكرة شاركها')} ${e(detail.author?.name||say('a Veelad member','عضو في فيلاد'))}</p><div class="creative-actions">${action(icon('heart')+say('I’d love this','ودي أشوفها')+' · '+number(detail.vote_count),'vote',`data-id="${e(detail.id)}" aria-pressed="${detail.viewer_voted===true}"`,'btn '+(detail.viewer_voted?'':'outline'))}${action(icon('users')+say('Follow the idea','تابع الفكرة')+' · '+number(detail.follower_count),'follow',`data-id="${e(detail.id)}" aria-pressed="${detail.viewer_following===true}"`,'btn '+(detail.viewer_following?'':'outline'))}</div>${notice('Following saves your interest to your account. It does not reserve a product or start a purchase.','المتابعة تحفظ اهتمامك في حسابك. ما تحجز منتج ولا تبدأ عملية شراء.')}</div><div class="creative-panel creative-wish-note"><span>✳</span><h3>${say('A conversation<br>waiting to become a design.','سالفة تنتظر<br>تصير تصميم.')}</h3></div></div><section class="creative-section"><div class="creative-section-heading"><h2>${say('Artists’ responses','ردود الفنانين')}</h2></div>${concepts.length?`<div class="creative-content-grid">${concepts.map(concept=>`<article class="creative-content-card">${concept.product?picture(concept.product):''}<div><p class="creative-kicker">${e(concept.author?.name||'')}</p><h3>${e(local(concept,'title'))}</h3><p>${e(local(concept,'description'))}</p>${concept.product?linkToProduct(concept.product):''}</div></article>`).join('')}</div>`:empty('The first response starts with an artist.','أول رد يبدأ من فنان.','No reviewed concepts have been published for this idea yet.','ما نُشرت تصوّرات معتمدة لهالفكرة إلى الآن.')}${user&&['artist','admin'].includes(user.role)?conceptForm(detail):''}</section></section>`);
    }
    return shell(`<section class="container creative-section">${title(say('THE WISH BOARD','لوحة الأفكار'),say('“Someone should<br>make this.”','«يا ليت أحد<br>يصمّمها». '),say('Ideas from customers. Possibilities for artists. Follow the ones you want to see take shape.','أفكار من العملاء، ومساحة للفنانين. تابع الفكرة اللي ودّك تشوفها تكبر.'),user?anchor(say('Share an idea','شارك فكرتك'),'creative/wishes','btn',{compose:'wish'}):anchor(say('Sign in to share','ادخل وشارك'),'login','btn',{next:'creative/wishes'}))}${activeParams.get('compose')==='wish'&&user?wishForm():''}${data.wishes?.wishes?.length?`<div class="creative-wish-grid">${data.wishes.wishes.map(wishCard).join('')}</div>${pagination(data.wishes.pagination,'creative/wishes')}`:empty('Make room for the first good idea.','خلّ مكان لأول فكرة حلوة.','The board starts with real people and reviewed ideas. Share something you genuinely wish existed.','اللوحة تبدأ بناس حقيقيين وأفكار نراجعها. شارك شي فعلًا تتمنى تشوفه.')}${notice('No money is collected on the wish board. Votes show interest, not guaranteed demand or production.','ما نجمع أي مبالغ في لوحة الأفكار. التصويت يعبّر عن اهتمام، مو ضمان طلب أو إنتاج.')}</section>`);
  }
  function conceptForm(wish) {
    const owned=data.workspace?.products||[];
    return `<form class="creative-form creative-panel" data-creative-form="concept"><h3>${say('An artist’s response','ردّك كفنان')}</h3><input type="hidden" name="wish_id" value="${e(wish.id)}">${field(say('Concept title','عنوان التصوّر'),'title','','required maxlength="160"')}${area(say('Describe your direction','وصف اتجاهك'),'description','','required maxlength="2400"')}${select(say('An existing product, if relevant','منتج موجود، إذا كان يناسب'), 'product_id',[{id:'',en:'No product attached',ar:'بدون منتج مرفق'},...owned.map(p=>({id:p.id,en:p.title,ar:p.title_ar||p.title}))])}<p class="creative-help">${say('A concept is a public creative response after review. Any future commercial agreement needs a separate discussion.','التصوّر رد إبداعي يظهر بعد المراجعة. أي اتفاق تجاري لاحق يحتاج نقاش مستقل.')}</p><button class="btn" type="submit">${say('Send concept for review','أرسل التصوّر للمراجعة')}</button><div data-creative-form-status role="status" aria-live="polite"></div></form>`;
  }
  function pagination(pagination,route){
    if(!pagination||pagination.total<=pagination.page_size)return '';
    const page=Number(pagination.page||0),query=Object.fromEntries(activeParams);delete query.id;
    return `<nav class="creative-pagination" aria-label="${say('Pagination','صفحات النتائج')}">${page?anchor(say('Previous','السابق'),route,'btn outline sm',{...query,page:page-1}):'<span></span>'}<span>${number(page+1)} / ${number(Math.ceil(pagination.total/pagination.page_size))}</span>${(page+1)*pagination.page_size<pagination.total?anchor(say('Next','التالي'),route,'btn outline sm',{...query,page:page+1}):'<span></span>'}</nav>`;
  }
  function contentCard(item,kind){
    const page=kind==='template'?'creative/templates':'creative/stories';
    return `<article class="creative-content-card">${item.product?anchor(picture(item.product),page,'creative-content-image',{id:item.id}):''}<div><div class="creative-card-top"><p class="creative-kicker">${e(item.author?.name||item.artist?.name||'')}</p>${item.status&&item.status!=='approved'?badge(item.status):''}</div><h3>${anchor(e(local(item,'title')),page,'',{id:item.id})}</h3><p>${e(local(item,'description'))}</p>${anchor(kind==='template'?say('Make it personal','أضف بصمتك'):say('Read the story','اقرأ الحكاية'),page,'text-link',{id:item.id})}</div></article>`;
  }
  function catalogue(kind){
    const template=kind==='template',items=template?data.templates?.templates||[]:data.stories?.stories||[],result=template?data.templates:data.stories,canAuthor=user&&['artist','admin'].includes(user.role),composition=activeParams.get('compose');
    const detail=template?data.template?.template:data.story?.story;
    if(detail)return template?templateDetail(detail):storyDetail(detail);
    return shell(`<section class="container creative-section">${title(template?say('ARTIST-DESIGNED. PERSONALLY YOURS.','من تصميم فنان، وبصمتك أنت.'):say('BEHIND THE DESIGN','وراء التصميم'),template?say('A beautiful beginning.<br>Your finishing touch.','بداية من فنان.<br>وتكمل بلمستك.'):say('Meet the story<br>behind the thing.','تعرّف على الحكاية<br>وراء القطعة.'),template?say('Original layouts with artist-chosen fields for names, dates and messages. You make it personal while the composition stays considered.','قوالب أصلية يحدد فيها الفنان مساحة للأسماء والتواريخ والرسائل. تضيف بصمتك، وتبقى روح التصميم.'):say('The inspiration, process and people behind independent art. These stories are shared by their artists and reviewed before publication.','الإلهام، والخطوات، والناس وراء الفن المستقل. حكايات يشاركها أصحابها ونراجعها قبل النشر.'),canAuthor?anchor(template?say('Create a layout','أنشئ قالب'):say('Share a design story','شارك حكاية تصميم'),template?'creative/templates':'creative/stories','btn',{compose:kind}):'')}${composition===kind&&canAuthor?(template?templateForm():storyForm()):''}${items.length?`<div class="creative-content-grid">${items.map(item=>contentCard(item,kind)).join('')}</div>${pagination(result.pagination,template?'creative/templates':'creative/stories')}`:empty(template?'The first personal touch is on its way.':'Every collection starts with a first story.',template?'أول لمسة شخصية بالطريق.':'كل مجموعة تبدأ بأول حكاية.',template?'Artist-approved layouts will appear here after review. You can still start with Veelad’s editable starter layouts in the design studio.':'Published artist stories will appear here after review. No fictional stories or artists are shown.',template?'تظهر قوالب الفنانين هنا بعد المراجعة. وتقدر تبدأ الآن من قوالب فيلاد القابلة للتعديل في الاستوديو.':'تظهر حكايات الفنانين هنا بعد المراجعة. ما نعرض حكايات أو أسماء خيالية.',template?anchor(say('Open the design studio','افتح استوديو التصميم'),'create','btn outline'):'')}</section>`);
  }
  function templateDetail(template){
    const composition=template.composition||{},fields=composition.fields||[];
    return shell(`<section class="container creative-section">${anchor('← '+say('Artist layouts','قوالب الفنانين'),'creative/templates','text-link')}${title(say('MAKE IT PERSONAL','خلّها تشبهك'),e(local(template,'title')),e(local(template,'description')))}<div class="creative-personalise-layout"><div><div class="creative-layout-preview" data-creative-template-preview style="--layout-background:${safeColor(composition.background,'#f3ede5')}">${template.product?picture(template.product):''}<div class="creative-layout-text">${fields.map(item=>`<span data-preview-field="${e(item.id)}">${e(currentLanguage()==='ar'?item.default_ar||item.default:item.default)}</span>`).join('')}</div></div><p class="creative-help">${say('Layout illustration. Final placement is reviewed in the product editor; this is not a calibrated physical sample.','رسم توضيحي للقالب. راجع موضعه في محرر المنتج؛ هذي مو عيّنة مادية مضبوطة.')}</p></div><form class="creative-form creative-panel" data-creative-form="personalize"><input type="hidden" name="template_id" value="${e(template.id)}"><input type="hidden" name="version" value="${e(template.version)}"><p class="creative-kicker">${say('BY','من')} ${e(template.author?.name||template.artist?.name||'')}</p><h2>${say('Your words go here.','هنا مكان كلماتك.')}</h2>${fields.map(item=>field(e(currentLanguage()==='ar'?item.label_ar||item.label:item.label),'value_'+item.id,currentLanguage()==='ar'?item.default_ar||item.default:item.default,`required maxlength="${Number(item.max_length)||40}" dir="auto" data-template-value="${e(item.id)}"`)).join('')}<p class="creative-help">${say('Only the artist-approved fields are personalised. Product availability and the original licence are checked before the design is prepared.','التخصيص يكون في الحقول اللي اعتمدها الفنان. نراجع إتاحة المنتج وترخيصه قبل تجهيز التصميم.')}</p><button class="btn" type="submit">${say('Open my personalised design','افتح التصميم بلمستي')} ${icon('arrow')}</button><div data-creative-form-status role="status" aria-live="polite"></div></form></div>${template.product?`<div class="creative-panel"><h3>${say('The original product','المنتج الأصلي')}</h3>${linkToProduct(template.product)}</div>`:''}</section>`);
  }
  function storyDetail(story){
    const sketches=story.sketches||story.sketch_products||[],gallery=story.gallery||[];
    const qr='/api.php?'+new URLSearchParams({route:'creative-story-qr',id:story.id,locale:currentLanguage()});
    return shell(`<article class="container creative-story-article creative-section">${anchor('← '+say('All design stories','كل حكايات التصاميم'),'creative/stories','text-link')}<div class="creative-story-heading"><p class="creative-kicker">${say('A DESIGN STORY BY','حكاية تصميم من')} ${e(story.author?.name||'')}</p><h1>${e(local(story,'title'))}</h1><p>${e(local(story,'description'))}</p></div>${story.product?`<figure class="creative-story-hero">${picture(story.product)}<figcaption>${e(local(story.product,'title'))}</figcaption></figure>`:''}<div class="creative-story-prose"><section><p class="creative-kicker">01 / ${say('THE SPARK','بداية الفكرة')}</p><h2>${say('Where it began.','من وين بدأت.')}</h2><p>${e(local(story,'inspiration'))}</p></section><section><p class="creative-kicker">02 / ${say('THE PROCESS','رحلة التصميم')}</p><h2>${say('From thought to form.','من فكرة لشكل.')}</h2><p>${e(local(story,'process'))}</p></section></div>${sketches.length?`<section><h2>${say('From the artist’s collection','من مجموعة الفنان')}</h2>${productCards(sketches,false)}</section>`:''}<section class="creative-story-keep creative-panel"><div><p class="creative-kicker">03 / ${say('KEEP THE STORY','خلّ الحكاية قريبة')}</p><h2>${say('More than a finished piece.','أكثر من قطعة جاهزة.')}</h2><p>${say('Save or share this page. The artist can include its QR code with their packaging, so the story travels with the design.','احفظ الصفحة أو شاركها. يقدر الفنان يضيف رمز الحكاية مع التغليف، عشان ترافق التصميم.')}</p><div class="creative-actions">${action(say('Copy story link','انسخ رابط الحكاية'),'share-story','','btn outline')}${story.product?linkToProduct(story.product):''}</div></div><a href="${e(qr)}" download="veelad-design-story.svg" class="creative-story-qr"><img src="${e(qr)}" width="144" height="144" alt="${say('QR code linking to this design story','رمز QR يفتح حكاية التصميم')}"><span>${say('Download story QR','نزّل رمز الحكاية')}</span></a></section><section class="creative-section"><div class="creative-section-heading"><h2>${say('Out in the world.','الحكاية معكم.')}</h2></div>${gallery.length?`<div class="creative-content-grid">${gallery.map(entry=>`<figure class="creative-gallery-card"><img src="${e(entry.image_url)}" alt="${e(entry.caption||say('A customer-shared product photo','صورة منتج شاركها عميل'))}" loading="lazy"><figcaption>${e(entry.caption||'')}</figcaption></figure>`).join('')}</div>`:notice('Customer photos appear only after explicit permission and review. No customer photo has been published for this story yet.','صور العملاء تظهر بعد موافقتهم الصريحة ومراجعتها. ما نُشرت صورة عميل لهالحكاية إلى الآن.')}${user?galleryForm(story):''}</section></article>`);
  }
  function galleryForm(story){
    return `<details class="creative-panel"><summary>${say('Share your finished piece','شاركنا قطعتك')}</summary><form class="creative-form" data-creative-form="gallery"><input type="hidden" name="story_id" value="${e(story.id)}">${field(say('Your photo · PNG or JPEG','صورتك · PNG أو JPEG'),'photo','','required accept="image/png,image/jpeg"','file')}${field(say('A short caption','وصف قصير'),'caption','','maxlength="300"')}${check(say('I own this photo, have permission from anyone visible, and agree to its public display on this design story after review.','أملك الصورة وعندي إذن من أي شخص يظهر فيها، وأوافق على نشرها في حكاية التصميم بعد المراجعة.'),'consent',false,'required')}<p class="creative-help">${say('Do not include addresses, private documents or other sensitive information. You can withdraw your photo from your creative workspace.','لا تظهر عناوين أو مستندات خاصة أو معلومات حساسة. وتقدر تسحب الصورة من مساحتك الإبداعية.')}</p><button class="btn outline" type="submit">${say('Send photo for review','أرسل الصورة للمراجعة')}</button><div data-creative-form-status role="status" aria-live="polite"></div></form></details>`;
  }
  function ownedProductOptions(){return (data.workspace?.products||[]).map(p=>({id:p.id,en:p.title,ar:p.title_ar||p.title}));}
  function storyForm(story={}){
    const productOptions=ownedProductOptions();
    if(!productOptions.length)return notice('Publish an original product first. Design stories must belong to an actual product you own.','انشر منتجًا أصليًا أولًا. حكاية التصميم لازم ترتبط بمنتج فعلي تملكه.');
    return `<form class="creative-form creative-panel" data-creative-form="story">${story.id?`<input type="hidden" name="id" value="${e(story.id)}"><input type="hidden" name="version" value="${e(story.version)}">`:''}<h2>${say('Tell the story in your own words.','احكِ الحكاية بصوتك.')}</h2>${select(say('Your original product','منتجك الأصلي'),'product_id',productOptions,story.product_id||story.product?.id)}<div class="creative-form-grid">${field(say('Title · English','العنوان · إنجليزي'),'title',story.title||'','required maxlength="160" dir="ltr"')}${field(say('Title · Arabic','العنوان · عربي'),'title_ar',story.title_ar||'','maxlength="160" dir="rtl"')}${area(say('Introduction · English','نبذة · إنجليزي'),'description',story.description||'','required maxlength="2000" dir="ltr"')}${area(say('Introduction · Arabic','نبذة · عربي'),'description_ar',story.description_ar||'','maxlength="2000" dir="rtl"')}${area(say('The inspiration · English','الإلهام · إنجليزي'),'inspiration',story.inspiration||'','required maxlength="5000" dir="ltr"')}${area(say('The inspiration · Arabic','الإلهام · عربي'),'inspiration_ar',story.inspiration_ar||'','maxlength="5000" dir="rtl"')}${area(say('Your process · English','رحلتك مع التصميم · إنجليزي'),'process',story.process||'','required maxlength="5000" dir="ltr"')}${area(say('Your process · Arabic','رحلتك مع التصميم · عربي'),'process_ar',story.process_ar||'','maxlength="5000" dir="rtl"')}</div><fieldset class="creative-choice-fieldset"><legend>${say('Related work from your collection','أعمال مرتبطة من مجموعتك')}</legend>${productOptions.map(option=>check(e(optionName(option)),'sketch_product_ids',story.sketch_product_ids?.includes(option.id),`value="${e(option.id)}"`)).join('')}</fieldset>${check(say('I have permission to publish this story and the approved product preview images.','عندي الإذن بنشر هالحكاية وصور معاينات المنتجات المعتمدة.'),'marketing_permission',false,'required')}<p class="creative-help">${say('Only approved product previews are public. Your high-resolution print originals remain private.','اللي يظهر للكل هو معاينات المنتجات المعتمدة فقط. ملفات الطباعة الأصلية عالية الدقة تبقى خاصة.')}</p><div class="creative-actions"><button class="btn" type="submit" name="action" value="submit">${say('Send story for review','أرسل الحكاية للمراجعة')}</button><button class="btn outline" type="submit" name="action" value="draft">${say('Save draft','احفظ مسودة')}</button></div><div data-creative-form-status role="status" aria-live="polite"></div></form>`;
  }
  const safeColor=(value,fallback='#25283d')=>/^#[0-9a-f]{6}$/i.test(value||'')?value:value==='transparent'?'transparent':fallback;
  function templateField(item={},index=0){
    return `<fieldset class="creative-template-field" data-creative-template-field><legend>${say('Editable field','حقل قابل للتعديل')} ${number(index+1)}</legend><input type="hidden" name="field_id" value="${e(item.id||'field-'+(index+1))}"><div class="creative-form-grid">${field(say('Label · English','اسم الحقل · إنجليزي'),'field_label',item.label||'Your name','required maxlength="80"')}${field(say('Label · Arabic','اسم الحقل · عربي'),'field_label_ar',item.label_ar||'اسمك','maxlength="80"')}${field(say('Starting text · English','نص البداية · إنجليزي'),'field_default',item.default||'YOUR NAME','required maxlength="160"')}${field(say('Starting text · Arabic','نص البداية · عربي'),'field_default_ar',item.default_ar||'اسمك هنا','maxlength="160"')}${field(say('Maximum characters','أقصى عدد حروف'),'field_max_length',item.max_length||40,'required min="1" max="160"','number')}${select(say('Font','الخط'),'field_font',[{id:'manrope',en:'Manrope',ar:'Manrope'},{id:'arabic',en:'Arabic',ar:'عربي'},{id:'arabic-bold',en:'Arabic bold',ar:'عربي عريض'},{id:'dm-sans',en:'DM Sans',ar:'DM Sans'}],item.font||'manrope')}${field(say('Text colour','لون النص'),'field_color',safeColor(item.color),'required','color')}${field(say('Horizontal position · %','الموضع الأفقي · %'),'field_x',Math.round((item.x??.5)*100),'required min="5" max="95"','number')}${field(say('Vertical position · %','الموضع العمودي · %'),'field_y',Math.round((item.y??(.35+index*.15))*100),'required min="5" max="95"','number')}${field(say('Text size · % of canvas','حجم النص · % من المساحة'),'field_size',Math.round((item.size??.08)*100),'required min="2" max="30" step="0.5"','number')}</div>${action(say('Remove this field','احذف الحقل'),'remove-template-field','','text-link')}</fieldset>`;
  }
  function templateForm(template={}){
    const options=ownedProductOptions(),composition=template.composition||{},fields=composition.fields?.length?composition.fields:[{}];
    if(!options.length)return notice('Publish an original product first. Personalisation layouts must belong to a product you own.','انشر منتجًا أصليًا أولًا. قالب التخصيص لازم يرتبط بمنتج تملكه.');
    return `<form class="creative-form creative-panel" data-creative-form="template">${template.id?`<input type="hidden" name="id" value="${e(template.id)}"><input type="hidden" name="version" value="${e(template.version)}">`:''}<h2>${say('Make a place for someone’s story.','خلّ في تصميمك مكان لحكاية أحد.')}</h2><p>${say('Choose your product, define the text fields and place them thoughtfully. Customers can edit those fields; your fixed composition remains protected.','اختر منتجك، وحدّد حقول النص ومكانها بعناية. العميل يعدّل هالحقول، والتكوين الثابت يبقى محفوظ.')}</p>${select(say('Your original product','منتجك الأصلي'),'product_id',options,template.product_id||template.product?.id)}<div class="creative-form-grid">${field(say('Layout title · English','عنوان القالب · إنجليزي'),'title',template.title||'','required maxlength="160"')}${field(say('Layout title · Arabic','عنوان القالب · عربي'),'title_ar',template.title_ar||'','maxlength="160"')}${area(say('Description · English','الوصف · إنجليزي'),'description',template.description||'','required maxlength="2000"')}${area(say('Description · Arabic','الوصف · عربي'),'description_ar',template.description_ar||'','maxlength="2000"')}${select(say('Print surface','جهة الطباعة'),'surface',[{id:'front',en:'Front',ar:'الأمام'},{id:'back',en:'Back',ar:'الخلف'},{id:'wrap',en:'Mug wrap',ar:'لفة الكوب'}],composition.surface||'front')}${field(say('Layout background','خلفية القالب'),'background',safeColor(composition.background,'#ffffff'),'required','color')}</div><div class="creative-author-composer"><div data-creative-template-fields>${fields.map(templateField).join('')}</div><aside><div class="creative-flat-preview" data-creative-flat-preview aria-label="${say('Flat text placement illustration','رسم توضيحي لموضع النص')}"></div><p class="creative-help">${say('Flat composition preview. Exact supplier print areas still require a calibrated product template.','معاينة مسطّحة للتكوين. مساحة الطباعة الدقيقة تحتاج قالب المنتج المعتمد من المورّد.')}</p></aside></div>${action(say('Add an editable field','أضف حقل قابل للتعديل'),'add-template-field','','btn outline sm')}${check(say('I own this design and grant customers permission to print the personalised version on this product.','أملك التصميم وأمنح العميل إذن طباعة نسخته المخصّصة على هالمنتج.'),'rights_confirmed',false,'required')}<div class="creative-actions"><button class="btn" type="submit" name="action" value="submit">${say('Send layout for review','أرسل القالب للمراجعة')}</button><button class="btn outline" type="submit" name="action" value="draft">${say('Save draft','احفظ مسودة')}</button></div><div data-creative-form-status role="status" aria-live="polite"></div></form>`;
  }
  function workspace(){
    if(!user)return shell(signIn());
    const own=data.workspace||{};
    return shell(`<section class="container creative-section">${title(say('YOUR CREATIVE WORKSPACE','مساحتك الإبداعية'),say('Ideas you’re<br>bringing to life.','أفكارك،<br>وهي تاخذ شكلها.'),say('Follow your submissions, read review feedback and keep your private drafts together.','تابع مشاركاتك، واقرأ ملاحظات المراجعة، واجمع مسوداتك الخاصة في مكان واحد.'),['artist','admin'].includes(user.role)?`<div class="creative-actions">${anchor(say('New artist layout','قالب فنان جديد'),'creative/templates','btn',{compose:'template'})}${anchor(say('New design story','حكاية تصميم جديدة'),'creative/stories','btn outline',{compose:'story'})}</div>`:'')}${['wishes','templates','stories','concepts'].map(kind=>`<section class="creative-workspace-section"><h2>${({wishes:say('Your ideas','أفكارك'),templates:say('Your layouts','قوالبك'),stories:say('Your stories','حكاياتك'),concepts:say('Your concepts','تصوّراتك')})[kind]}</h2>${own[kind]?.length?`<div class="creative-workspace-list">${own[kind].map(item=>`<article class="creative-panel"><div class="creative-card-top"><h3>${e(local(item,'title'))}</h3>${badge(item.status)}</div><p>${e(local(item,'description'))}</p>${item.feedback?`<p class="creative-review-feedback">${say('Review feedback: ','ملاحظات المراجعة: ')}${e(item.feedback)}</p>`:''}<div class="creative-actions">${kind==='wishes'?anchor(say('View idea','شوف الفكرة'),'creative/wishes','text-link',{id:item.id}):kind==='templates'?anchor(say('Edit layout','عدّل القالب'),'creative/templates','text-link',{compose:'template',edit:item.id}):kind==='stories'?anchor(say('Edit story','عدّل الحكاية'),'creative/stories','text-link',{compose:'story',edit:item.id}):''}${kind==='wishes'&&item.status!=='cancelled'?action(say('Withdraw this idea','اسحب الفكرة'),'cancel-wish',`data-id="${e(item.id)}" data-version="${e(item.version)}"`,'text-link'):''}</div></article>`).join('')}</div>`:notice('Nothing here yet. Your own submissions will appear as you create them.','ما فيه شي هنا إلى الآن. مشاركاتك تظهر لما تبدأ تنشئها.')}</section>`).join('')}${own.gallery?.length?`<section><h2>${say('Your shared photos','صورك المشتركة')}</h2>${own.gallery.map(item=>`<div class="creative-panel"><p>${e(item.caption||'')}</p>${badge(item.status)}${action(say('Withdraw photo','اسحب الصورة'),'withdraw-gallery',`data-id="${e(item.id)}"`,'text-link')}</div>`).join('')}</section>`:''}</section>`);
  }
  function administration(){
    const result=data.admin||{},kinds=[['wishes','wish','Ideas','الأفكار'],['concepts','concept','Artist concepts','تصوّرات الفنانين'],['templates','template','Personalisation layouts','قوالب التخصيص'],['stories','story','Design stories','حكايات التصاميم'],['gallery','gallery','Customer photos','صور العملاء']];
    return `<section class="creative-page creative-admin">${title(say('CREATIVE COMMUNITY REVIEW','مراجعة المجتمع الإبداعي'),say('Make room for<br>good, original ideas.','مساحة للأفكار<br>الحلوة والأصلية.'),say('Review the actual content, rights confirmation and product connection before publishing. A rejection reason is visible to the creator.','راجع المحتوى الفعلي وإقرار الحقوق وارتباطه بالمنتج قبل النشر. سبب طلب التعديل يظهر لصاحب المشاركة.'))}<nav class="creative-admin-nav" aria-label="${say('Creative review sections','أقسام المراجعة الإبداعية')}">${kinds.map(([key,,en,ar])=>`<a href="#creative-review-${key}">${say(en,ar)} <span>${number(result[key]?.length||0)}</span></a>`).join('')}</nav>${kinds.map(([key,kind,en,ar])=>`<section class="creative-review-section" id="creative-review-${key}"><h2>${say(en,ar)}</h2>${result[key]?.length?result[key].map(item=>`<article class="creative-panel creative-review-card"><div class="creative-card-top"><h3>${e(local(item,'title')||item.caption||say('Customer photo','صورة عميل'))}</h3>${badge(item.status)}</div><p>${e(local(item,'description')||'')}</p><p class="creative-help">${say('Created by','من')} ${e(item.author?.name||item.artist?.name||'')}</p>${item.product?linkToProduct(item.product):''}${item.inspiration?`<details><summary>${say('Read the process and inspiration','اقرأ الإلهام والخطوات')}</summary><p>${e(item.inspiration)}</p><p>${e(item.process||'')}</p></details>`:''}${item.composition?`<details><summary>${say('Review editable fields and composition','راجع حقول النص والتكوين')}</summary><pre>${e(JSON.stringify(item.composition,null,2))}</pre></details>`:''}${item.image_url?`<img class="creative-review-image" src="${e(item.image_url)}" alt="${e(item.caption||say('Submitted photo','صورة للمراجعة'))}">`:''}<form class="creative-form" data-creative-form="review"><input type="hidden" name="kind" value="${kind}"><input type="hidden" name="id" value="${e(item.id)}"><input type="hidden" name="version" value="${e(item.version)}"><div class="creative-form-grid">${select(say('Decision','القرار'),'status',[{id:'approved',en:'Approve and publish',ar:'اعتماد ونشر'},{id:'rejected',en:'Request changes',ar:'طلب تعديل'}])}${field(say('Review reason','سبب القرار'),'reason','','required maxlength="1000"')}</div><button class="btn outline" type="submit">${say('Record review','سجّل المراجعة')}</button><div data-creative-form-status role="status" aria-live="polite"></div></form></article>`).join(''):notice('No submissions waiting in this section.','ما فيه مشاركات تنتظر بهالقسم.')}</section>`).join('')}</section>`;
  }
  function handles(route,params){return route==='creative'||route.startsWith('creative/')||(route==='admin'&&params.get('tab')==='creative');}
  async function renderPage(route,params){
    activeRoute=route;activeParams=new URLSearchParams(params);data={};lastGuide=null;
    if(route.startsWith('creative/rooms')&&window.VeeladDesignRooms)return window.VeeladDesignRooms.render(route,params);
    if(route==='creative/sample-room'&&window.VeeladSampleRoom)return window.VeeladSampleRoom.render(route,params);
    if(route==='admin'){
      if(user?.role!=='admin')throw Error(say('Administrator access is required.','هالمساحة للمسؤولين فقط.'));
      data.admin=await api('admin-creative');return administration();
    }
    data.discover=await api('creative-discover');
    const id=params.get('id')||route.split('/')[2];
    if(route==='creative')return landing();
    if(route==='creative/story')return user?guideForm('brief'):shell(signIn());
    if(route==='creative/gifts')return guideForm('gift');
    if(route==='creative/taste')return taste();
    if(route==='creative/workspace'){if(user)data.workspace=await api('creative-workspace');return workspace();}
    if(route.startsWith('creative/wishes')){
      if(id)data.wish=await api('creative-wish',null,{id});else data.wishes=await api('creative-wishes',null,Object.fromEntries(params));
      if(user&&['artist','admin'].includes(user.role))data.workspace=await api('creative-workspace');return wishes();
    }
    if(route.startsWith('creative/templates')||route.startsWith('creative/stories')){
      const template=route.startsWith('creative/templates');
      if(id)data[template?'template':'story']=await api(template?'creative-template':'creative-story',null,{id});else data[template?'templates':'stories']=await api(template?'creative-templates':'creative-stories',null,Object.fromEntries(params));
      if(user&&params.get('compose'))data.workspace=await api('creative-workspace');
      return catalogue(template?'template':'story');
    }
    return shell(empty('A new creative space.','مساحة إبداعية جديدة.','This experience is not available here. Choose another path above.','هالتجربة مو متاحة هنا. اختر مساحة ثانية من القائمة.'));
  }
  function formError(form,error){let node=form.querySelector('[data-creative-form-status]');if(!node){node=document.createElement('p');node.setAttribute('data-creative-form-status','');node.setAttribute('role','alert');form.append(node);}node.className='creative-form-message error';node.textContent=error.message||String(error);node.setAttribute('role','alert');node.scrollIntoView({block:'nearest'});}
  function formSuccess(form,message){const node=form.querySelector('[data-creative-form-status]');if(node){node.className='creative-form-message success';node.textContent=message;node.setAttribute('role','status');}}
  function decimal(value){if(value===''||value===null)return undefined;if(!/^\d+(?:\.\d{1,2})?$/.test(String(value)))throw Error(say('Enter a budget with at most two decimal places.','اكتب الميزانية برقم ومنزلتين عشريتين كحد أقصى.'));const [whole,fraction='']=String(value).split('.');return Number(whole)*100+Number(fraction.padEnd(2,'0'));}
  function templateComposition(form){
    const fields=[...form.querySelectorAll('[data-creative-template-field]')].map(root=>{
      const get=name=>root.querySelector('[name='+name+']').value;
      return {id:get('field_id'),label:get('field_label'),label_ar:get('field_label_ar'),default:get('field_default'),default_ar:get('field_default_ar'),max_length:Number(get('field_max_length')),x:Number(get('field_x'))/100,y:Number(get('field_y'))/100,size:Number(get('field_size'))/100,font:get('field_font'),color:get('field_color'),align:'center',direction:'auto'};
    });
    return {background:form.elements.background.value,surface:form.elements.surface.value,fields,fixed_text:[]};
  }
  function updateFlatPreview(form){
    const mount=form.querySelector('[data-creative-flat-preview]');if(!mount)return;
    const composition=templateComposition(form);mount.style.background=safeColor(composition.background,'#fff');
    mount.innerHTML=composition.fields.map(item=>`<span style="left:${item.x*100}%;top:${item.y*100}%;font-size:${item.size*250}px;color:${safeColor(item.color)};font-family:${item.font.startsWith('arabic')?'Veelad Arabic':'Manrope'}">${e(currentLanguage()==='ar'?item.default_ar||item.default:item.default)}</span>`).join('');
  }
  async function handoff(payload){
    if(window.VeeladCreativeEditor?.handoff)return window.VeeladCreativeEditor.handoff(payload);
    if(window.VeeladCreativeEditor?.startConcept&&payload.concept)return window.VeeladCreativeEditor.startConcept(payload);
    throw Error(say('The creative editor is still loading. Refresh and try again.','محرر الإبداع لسه يجهز. حدّث الصفحة وجرّب مرّة ثانية.'));
  }
  async function submit(form,submitter){
    const values=Object.fromEntries(new FormData(form)),kind=form.dataset.creativeForm,checked=name=>form.elements[name]?.checked===true;
    if(kind==='brief'||kind==='gift'){
      const payload={recipient:values.recipient,occasion:values.occasion,story:values.story,mood:values.mood,category:values.category,language:currentLanguage(),...(decimal(values.budget)!==undefined?{budget_minor:decimal(values.budget)}:{}),...(kind==='gift'?{save:checked('save')}:{})};
      lastGuide=await api(kind==='gift'?'creative-gift-guide':'creative-brief',payload);
      const mount=document.querySelector('[data-creative-results]');mount.innerHTML=guideResults(lastGuide);mount.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});formSuccess(form,say('Your direction is ready below.','اتجاه تصميمك جاهز تحت.'));return;
    }
    if(kind==='taste'){
      await api('creative-taste',{consent:checked('consent'),styles:new FormData(form).getAll('styles'),colors:new FormData(form).getAll('colors'),moods:new FormData(form).getAll('moods'),language:currentLanguage(),...(values.version?{version:Number(values.version)}:{})});
      await window.render({preserveScroll:true});toast(say('Your taste is saved.','حفظنا ذوقك.'));return;
    }
    if(kind==='wish'){
      await api('creative-wish',{title:values.title,description:values.description,category:values.category,action:submitter?.value||'submit',...(values.id?{id:values.id,version:Number(values.version)}:{})});
      location.assign(url('creative/workspace'));return;
    }
    if(kind==='concept'){
      await api('creative-concept',{wish_id:values.wish_id,title:values.title,description:values.description,...(values.product_id?{product_id:values.product_id}:{}),action:'submit'});form.reset();formSuccess(form,say('Your concept is with the review team.','وصل تصوّرك لفريق المراجعة.'));return;
    }
    if(kind==='story'){
      const payload={...values,action:submitter?.value||'submit',marketing_permission:checked('marketing_permission'),sketch_product_ids:new FormData(form).getAll('sketch_product_ids')};if(values.version)payload.version=Number(values.version);
      await api('creative-story',payload);location.assign(url('creative/workspace'));return;
    }
    if(kind==='template'){
      const composition=templateComposition(form),payload={title:values.title,title_ar:values.title_ar,description:values.description,description_ar:values.description_ar,product_id:values.product_id,composition,allowed_fonts:[...new Set(composition.fields.map(item=>item.font))],palette:[...new Set(composition.fields.map(item=>item.color))],rights_confirmed:checked('rights_confirmed'),action:submitter?.value||'submit',...(values.id?{id:values.id,version:Number(values.version)}:{})};
      await api('creative-template',payload);location.assign(url('creative/workspace'));return;
    }
    if(kind==='personalize'){
      const template=data.template.template,payload=Object.fromEntries((template.composition?.fields||[]).map(item=>[item.id,values['value_'+item.id]]));
      await handoff({source:'template',template_id:values.template_id,version:Number(values.version),values:payload,product_id:template.product?.id||template.product_id});return;
    }
    if(kind==='review'){
      await api('admin-creative-review',{kind:values.kind,id:values.id,version:Number(values.version),status:values.status,reason:values.reason});await window.render({preserveScroll:true});return;
    }
    if(kind==='gallery'){
      const file=form.elements.photo.files[0];if(!file||file.size>8*1024*1024)throw Error(say('Choose a PNG or JPEG photo no larger than 8 MB.','اختر صورة PNG أو JPEG بحجم ٨ ميغابايت أو أقل.'));
      const body=new FormData();body.append('artwork',file);const response=await fetch('/api.php?route=upload',{method:'POST',headers:{'X-CSRF-Token':csrf},body,credentials:'same-origin'});const upload=await response.json();if(!response.ok)throw Error(upload.error||'Upload failed.');
      await api('creative-contribution',{story_id:values.story_id,caption:values.caption,consent:checked('consent'),upload_id:upload.upload_id});form.reset();formSuccess(form,say('Your photo is private until it is reviewed.','صورتك تبقى خاصة إلى ما نراجعها.'));return;
    }
  }
  async function click(control){
    const kind=control.dataset.creativeAction;
    if(kind==='delete-taste'){await api('creative-taste',{action:'delete'});await window.render({preserveScroll:true});toast(say('Your saved taste was deleted.','حذفنا تفضيلاتك المحفوظة.'));return;}
    if(kind==='vote'||kind==='follow'){
      if(!user){location.assign(url('login',{next:'creative/wishes'}));return;}
      await api('creative-wish-interest',{wish_id:control.dataset.id,kind,active:control.getAttribute('aria-pressed')!=='true'});await window.render({preserveScroll:true});return;
    }
    if(kind==='cancel-wish'){await api('creative-wish',{id:control.dataset.id,version:Number(control.dataset.version),action:'cancel'});await window.render({preserveScroll:true});return;}
    if(kind==='start-concept'){
      const brief=lastGuide?.brief||lastGuide,product_id=document.querySelector('[data-creative-guide-product]')?.value;
      await handoff({source:activeRoute==='creative/gifts'?'gift':'brief',concept:brief.concept,brief_id:brief.id||null,product_id});return;
    }
    if(kind==='share-story'){const link=location.origin+url('creative/stories',{id:data.story.story.id});await navigator.clipboard.writeText(link);toast(say('Story link copied.','نسخنا رابط الحكاية.'));return;}
    if(kind==='add-template-field'){
      const form=control.closest('form'),mount=form.querySelector('[data-creative-template-fields]'),count=mount.children.length;if(count>=8)throw Error(say('Use up to eight editable text fields.','تقدر تضيف ثمانية حقول نص كحد أقصى.'));
      const nextId='field-'+Date.now().toString(36);mount.insertAdjacentHTML('beforeend',templateField({id:nextId},count));updateFlatPreview(form);return;
    }
    if(kind==='remove-template-field'){
      const form=control.closest('form');if(form.querySelectorAll('[data-creative-template-field]').length<=1)throw Error(say('Keep at least one editable field.','خلّ حقل واحد قابل للتعديل على الأقل.'));control.closest('[data-creative-template-field]').remove();updateFlatPreview(form);return;
    }
    if(kind==='withdraw-gallery'){await api('creative-contribution',{id:control.dataset.id,action:'withdraw'});await window.render({preserveScroll:true});return;}
  }
  document.addEventListener('submit',async event=>{
    const form=event.target;if(!form.matches('[data-creative-form]'))return;event.preventDefault();if(form.dataset.saving||!form.reportValidity())return;
    form.dataset.saving='true';const button=event.submitter;if(button)button.disabled=true;
    try{await submit(form,event.submitter);}catch(error){formError(form,error);}finally{delete form.dataset.saving;if(button?.isConnected)button.disabled=false;}
  });
  document.addEventListener('click',async event=>{
    const control=event.target.closest('[data-creative-action]');if(!control)return;event.preventDefault();if(control.disabled)return;control.disabled=true;
    try{await click(control);}catch(error){formError(control.closest('form,.creative-panel,.creative-page')||control.parentElement,error);}finally{if(control.isConnected)control.disabled=false;}
  });
  document.addEventListener('input',event=>{
    const form=event.target.closest('[data-creative-form=template]');if(form)updateFlatPreview(form);
    const input=event.target.closest('[data-template-value]');if(input){const target=document.querySelector('[data-preview-field="'+CSS.escape(input.dataset.templateValue)+'"]');if(target)target.textContent=input.value;}
  });
  function init(){
    if(activeRoute.startsWith('creative/rooms'))return window.VeeladDesignRooms?.init();
    if(activeRoute==='creative/sample-room')return window.VeeladSampleRoom?.init();
    document.querySelectorAll('[data-creative-form=template]').forEach(updateFlatPreview);
    const active=document.querySelector('.creative-navigation [aria-current=page]');if(active){const nav=active.parentElement,bounds=nav.getBoundingClientRect(),rect=active.getBoundingClientRect();if(rect.left<bounds.left||rect.right>bounds.right)nav.scrollBy({left:rect.left<bounds.left?rect.left-bounds.left:rect.right-bounds.right,behavior:'instant'});}
  }
  return {handles,render:renderPage,init,homeSection:()=>`<section class="container section creative-home-entry"><p class="creative-kicker">${say('MORE THAN A PRODUCT','فكرة لها حكاية')}</p><h2>${say('Make something that means something.','ابتكر قطعة لها معنى.')}</h2><p>${say('A personal story, a thoughtful gift, a shared idea. Find your starting point.','حكاية شخصية، هدية بمعنى، أو فكرة تجمعكم. اختر من وين تبدأ.')}</p><div class="creative-actions">${anchor(say('Explore the creative hub','اكتشف مساحة الإبداع'),'creative','btn')}${anchor(say('Find a gift','اختار هدية'),'creative/gifts','btn outline')}${anchor(say('Create together','ابتكروا مع بعض'),'creative/rooms','text-link')}</div></section>`};
})();
